from .common import code, case

def s(day,title,prompt,body,checks='',prefix='',suffix='',memory=False):
    return code(day,'S',title,prompt,[case('Контракт и граничные значения',body)],checks=checks,prefix=prefix,suffix=suffix,memory=memory)

# These compile real C++ and accept equivalent spellings. No string equality is
# used for grading. Context is explicitly shown by the exercise UI.
s(1,'Приватные координаты','Объявите class Point с тремя приватными double x_, y_, z_. Добавьте public-конструктор по умолчанию с нулями и const-методы x(), y(), z(), возвращающие double. Заголовки включите самостоятельно.', 'const Point p; CHECK(p.x()==0 && p.y()==0 && p.z()==0);', 'static_assert(std::is_class_v<Point>);',)
s(1,'Список инициализации','Определите class Pair с приватными const int first_, second_. Конструктор принимает два int, const-методы first() и second() возвращают их значения. Используйте список инициализации.', 'const Pair p(3,9); CHECK(p.first()==3 && p.second()==9); const Pair q(-2,0); CHECK(q.first()==-2);')
s(1,'Конструктор по умолчанию','Напишите class Counter. Конструктор без аргументов задаёт значение 0; explicit-конструктор принимает int. Метод value() доступен const-объектам и возвращает int.', 'const Counter a; Counter b(7); CHECK(a.value()==0 && b.value()==7);','static_assert(!std::is_convertible_v<int,Counter>);')
s(1,'Длина вектора','Напишите class Vec с конструктором из трёх double и методом length для const-объектов. Метод возвращает евклидову длину как double. Добавьте нужный заголовок.', 'const Vec v(2,3,6); CHECK(std::abs(v.length()-7)<1e-12); CHECK(Vec(0,0,0).length()==0);','static_assert(std::is_same_v<decltype(std::declval<const Vec&>().length()),double>);')
s(1,'Бинарный плюс','Создайте struct Number с публичным int value. Реализуйте сложение двух Number без изменения аргументов; результат — Number по значению.', 'const Number a{3},b{8}; auto c=a+b; CHECK(c.value==11 && a.value==3 && b.value==8);','static_assert(std::is_same_v<decltype(Number{}+Number{}),Number>);')
s(1,'Бинарный минус','Создайте struct Number с int value и бинарным вычитанием. const-операнды сохраняются, результат возвращается по значению.', 'const Number a{3},b{8}; CHECK((a-b).value==-5); CHECK(a.value==3);')
s(1,'Унарный минус','Создайте struct Number с int value, унарными плюс и минус для const-объектов. Оба возвращают новые Number.', 'const Number n{-7}; CHECK((-n).value==7 && (+n).value==-7 && n.value==-7);')
s(1,'Составное сложение','Создайте struct Number с int value и составным сложением. Поддержите (a+=b)+=c с изменением именно a.', 'Number a{1}; const Number b{2},c{3}; CHECK(&((a+=b)+=c)==&a); CHECK(a.value==6);','static_assert(std::is_same_v<decltype(std::declval<Number&>()+=std::declval<const Number&>()),Number&>);')
s(1,'Равенство','Создайте struct Pair с int x,y и сравнением ==. Оба поля должны совпадать; const-объекты поддерживаются.', 'const Pair a{1,2},b{1,2},c{1,3}; CHECK(a==b); CHECK(!(a==c));','static_assert(std::is_same_v<decltype(Pair{}==Pair{}),bool>);')
s(1,'Неравенство','Создайте struct Pair с int x,y и операторами ==, !=. Проверьте согласованность двух сравнений.', 'const Pair a{1,2},b{2,2}; CHECK(a!=b); CHECK(!(a!=a)); CHECK(!(a==b));')
s(1,'Индекс для записи','Создайте class Cell с одним int, конструктор принимает int. Через c[0] можно изменить хранимый объект. Другие индексы бросают std::out_of_range. Параметр индекса — std::size_t.', 'Cell c(4); c[0]=9; CHECK(c[0]==9); expect_throw<std::out_of_range>([&]{(void)c[1];});','static_assert(std::is_same_v<decltype(std::declval<Cell&>()[0]),int&>);')
s(1,'Индекс для чтения','Создайте class Cell(int) с двумя перегрузками индекса. Индекс 0 возвращает ссылку на хранимый int, остальные бросают out_of_range. Константная перегрузка запрещает запись.', 'Cell c(4); const Cell& r=c; CHECK(r[0]==4); c[0]=7; CHECK(r[0]==7); expect_throw<std::out_of_range>([&]{(void)r[1];});','static_assert(std::is_same_v<decltype(std::declval<const Cell&>()[0]),const int&>);')
s(1,'Функциональный объект','Создайте class Affine(double a,double b) и const-оператор вызова, вычисляющий a*x+b. Результат имеет тип double.', 'const Affine f(2,3); CHECK(f(4)==11); CHECK(f(-1)==1); CHECK(f(0)==3);')
s(1,'Скаляр слева','Создайте struct Vector3 с public double x,y,z. Реализуйте свободное умножение double * const Vector3&, возвращающее Vector3.', 'const Vector3 a{1,-2,3}; auto b=2.5*a; CHECK(b.x==2.5 && b.y==-5 && b.z==7.5 && a.x==1);')
s(1,'Дружественный вывод','Создайте class Secret с приватным int value_, explicit-конструктором из int и дружественным свободным оператором вывода. Формат: одно число. Поддержите цепочку.', 'const Secret s(17); std::ostringstream out; CHECK(&(out<<s)==&out); out<<":"<<Secret(-2); CHECK(out.str()=="17:-2");')
s(1,'Метод за пределами класса','В контексте дан Meter. Напишите вне класса определение его const-метода value. Метод возвращает n_.', 'const Meter m(9); CHECK(m.value()==9);',prefix='class Meter { int n_; public: explicit Meter(int n):n_(n){} int value() const; };\n')
s(1,'Копирующий конструктор','В контексте объявлен Label. Определите его конструктор копирования вне класса, сохранив значение number_.', 'const Label a(42); Label b(a); CHECK(b.value()==42);',prefix='class Label { int number_; public: explicit Label(int n):number_(n){} Label(const Label&); int value() const{return number_;} };\n')
s(1,'Возврат this','В контексте объявлен Accumulator. Определите add вне класса: увеличить n_ на v и вернуть изменяемую ссылку на текущий объект.', 'Accumulator a; CHECK(&a.add(2).add(3)==&a); CHECK(a.value()==5);',prefix='class Accumulator { int n_=0; public: Accumulator& add(int v); int value() const{return n_;} };\n')

s(2,'Выделение массива','Напишите int* make_zeros(std::size_t n): новый массив int[n], все элементы нулевые. Владение передаётся вызывающему коду, который использует delete[]. n=0 допустим.', 'int* p=make_zeros(5); for(int i=0;i<5;++i) CHECK(p[i]==0); delete[] p; delete[] make_zeros(0);',memory=True)
s(2,'Освобождение и обнуление','Напишите release(int*& p): освободить массив new[] и обнулить исходный указатель. Повторный вызов допустим.', 'int* p=new int[3]; release(p); CHECK(p==nullptr); release(p);',memory=True)
s(2,'Копия буфера','Напишите char* clone_text(const char* text): независимая копия C-строки через new[], включая ноль. nullptr → invalid_argument. Владение у вызывающего.', 'char a[]="abc"; char* p=clone_text(a); a[0]=char(120); CHECK(std::strcmp(p,"abc")==0); delete[] p; p=clone_text(""); CHECK(p[0]==0); delete[] p; expect_throw<std::invalid_argument>([]{clone_text(nullptr);});',memory=True)
s(2,'Конструктор из строки','Создайте class Text, владеющий new[]-буфером. explicit-конструктор из const char* отвергает nullptr; c_str() const возвращает const char*. Деструктор освобождает память. Копирование явно запретите.', 'char raw[]="abc"; const Text t(raw); raw[0]=char(120); CHECK(std::strcmp(t.c_str(),"abc")==0); expect_throw<std::invalid_argument>([]{Text t(nullptr);});',memory=True)
s(2,'Копирование владельца','Создайте class Text: конструктор из const char*, глубокий копирующий конструктор, деструктор, const c_str() и char& operator[](size_t) с проверкой границы. nullptr → invalid_argument. Присваивание можно запретить.', 'Text a("cat"); Text b(a); b[0]=char(98); CHECK(std::strcmp(a.c_str(),"cat")==0 && std::strcmp(b.c_str(),"bat")==0);',memory=True)
s(2,'Копирующее присваивание','Создайте class Text с правилом трёх и c_str() const. Конструктор из строки отвергает nullptr. Самоприсваивание и цепочка должны быть безопасны; каждая копия владеет собственным new[]-буфером.', 'Text a("a"),b("bb"),c("ccc"); CHECK(&(a=b=c)==&a); CHECK(std::strcmp(a.c_str(),"ccc")==0); a=a; CHECK(std::strcmp(a.c_str(),"ccc")==0);',memory=True)
s(2,'Деструктор владельца','В данном классе определите только деструктор вне объявления. Он должен освободить принадлежащий классу массив.', 'for(int i=0;i<40;++i){Buffer b;}',prefix='#include <cstddef>\nclass Buffer { char* data_=new char[32]{}; public: Buffer()=default; Buffer(const Buffer&)=delete; ~Buffer(); };\n',memory=True)
s(2,'Доступ к C-строке','Определите вне класса метод c_str. Возвращается const char*, метод должен работать на const Text. Контекст содержит декларацию.', 'const Text t; CHECK(std::strcmp(t.c_str(),"abc")==0);','static_assert(std::is_same_v<decltype(std::declval<const Text&>().c_str()),const char*>);',prefix='class Text { char data_[4]="abc"; public: const char* c_str() const; };\n')
s(2,'Размер объекта','Определите вне класса size: std::size_t, const, noexcept. Он возвращает size_.', 'const Text t; CHECK(t.size()==3);','static_assert(noexcept(std::declval<const Text&>().size()));',prefix='#include <cstddef>\nclass Text { std::size_t size_=3; public: std::size_t size() const noexcept; };\n')
s(2,'Две версии []','Определите обе перегрузки индекса Text вне класса. Индексы 0..2 доступны, остальные бросают out_of_range; ноль не является редактируемым элементом.', 'Text t; t[1]=char(120); const Text& c=t; CHECK(c[1]==char(120)); expect_throw<std::out_of_range>([&]{(void)c[3];});',prefix='#include <cstddef>\n#include <stdexcept>\nclass Text { char data_[4]="abc"; public: char& operator[](std::size_t); const char& operator[](std::size_t) const; };\n')
s(2,'Сравнение содержимого','Напишите bool equal_text(const char*,const char*): сравнивает C-строки по содержимому, nullptr в любом аргументе → invalid_argument.', 'char a[]="same",b[]="same"; CHECK(equal_text(a,b)); CHECK(!equal_text("a","aa")); expect_throw<std::invalid_argument>([]{equal_text(nullptr,"");});')
s(2,'Составная операция','Создайте class Text на собственном new[]-буфере с конструктором из строки, c_str(), правилом трёх и += для const Text&. Учтите t+=t, пустые строки и возврат ссылки. nullptr запрещён.', 'Text t("ab"); CHECK(&(t+=t)==&t); CHECK(std::strcmp(t.c_str(),"abab")==0); t+=Text(""); CHECK(std::strcmp(t.c_str(),"abab")==0);',memory=True)
s(2,'Обработка исключения','Напишите int guarded(int (*fn)()): вызвать fn и вернуть его результат; при std::out_of_range вернуть -1; другие исключения пропустить.', 'CHECK(guarded(+[]{return 7;})==7); CHECK(guarded(+[]()->int{throw std::out_of_range("x");})==-1); expect_throw<std::runtime_error>([]{guarded(+[]()->int{throw std::runtime_error("x");});});')
s(2,'Неверный аргумент','Напишите require_text(const char*): для nullptr бросить invalid_argument, для пустой/непустой строки завершиться нормально.', 'require_text(""); require_text("x"); expect_throw<std::invalid_argument>([]{require_text(nullptr);});')
s(2,'Границы','Напишите std::size_t checked_index(std::size_t size,std::size_t index): вернуть index при index<size, иначе out_of_range.', 'CHECK(checked_index(3,2)==2); expect_throw<std::out_of_range>([]{checked_index(0,0);}); expect_throw<std::out_of_range>([]{checked_index(3,3);});')
s(2,'Переполнение','Напишите std::size_t buffer_size(std::size_t a,std::size_t b): вернуть a+b+1, либо length_error до переполнения. Единица резервирует завершающий ноль.', 'CHECK(buffer_size(0,0)==1 && buffer_size(3,4)==8); const auto m=std::numeric_limits<std::size_t>::max(); expect_throw<std::length_error>([&]{buffer_size(m,0);}); expect_throw<std::length_error>([&]{buffer_size(m-1,1);});')
s(2,'Сохранение при неудаче','Напишите replace_copy(char*& target,const char* source). target владеет new[]-строкой. Сначала подготовьте новую копию, затем замените ресурс. nullptr → invalid_argument, target при ошибке неизменен; источник может равняться target+1.', 'char* p=new char[4]{char(97),char(98),char(99),0}; expect_throw<std::invalid_argument>([&]{replace_copy(p,nullptr);}); CHECK(std::strcmp(p,"abc")==0); replace_copy(p,p+1); CHECK(std::strcmp(p,"bc")==0); delete[] p;',memory=True)
s(2,'Перекрывающийся сдвиг','Напишите void remove_first(char* text): убрать первый символ через memmove, включая ноль. Пустая строка сохраняется; nullptr → invalid_argument.', 'char a[]="abc"; remove_first(a); CHECK(std::strcmp(a,"bc")==0); char b[]=""; remove_first(b); CHECK(b[0]==0); expect_throw<std::invalid_argument>([]{remove_first(nullptr);});')

s(3,'Объявление шаблона','Напишите только объявление шаблона identity: принимает значение T и возвращает T. Определение уже дано после вашего фрагмента.', 'CHECK(identity(3)==3); CHECK(identity(2.5)==2.5);',suffix='\ntemplate<class T> T identity(T x){return x;}\n')
s(3,'Определение шаблона','Напишите identity: шаблон с одним типом, принимает и возвращает значение этого типа.', 'CHECK(identity(4)==4); CHECK(identity(2.5)==2.5); CHECK(identity(std::string("x"))=="x");')
s(3,'Два параметра типа','Напишите sum для двух независимо выводимых типов. Результат имеет тип выражения a+b.', 'CHECK(sum(2,3.5)==5.5); CHECK(sum(3.5,2)==5.5);','static_assert(std::is_same_v<decltype(sum(2,3.5)),double>);')
s(3,'Ссылочные параметры','Напишите swap_values для двух изменяемых объектов одного T. Используйте копирование, STL-алгоритмы запрещены.', 'int a=1,b=2; swap_values(a,b); CHECK(a==2 && b==1); swap_values(a,a); CHECK(a==2);')
s(3,'Явный аргумент','Контекст содержит maximum. Напишите double mixed(): вызовите его с 2.5 и 3, явно выбрав тип double.', 'CHECK(mixed()==3.0);',prefix='template<class T> T maximum(T a,T b){return a<b?b:a;}\n')
s(3,'Полная специализация','Контекст содержит maximum(T,T). Напишите полную специализацию для const char*: сравнение содержимого, при равенстве первый аргумент, nullptr → invalid_argument. Не добавляйте обычную перегрузку вместо специализации.', 'const char a[]="az",b[]="ba"; CHECK(maximum<const char*>(a,b)==b); expect_throw<std::invalid_argument>([]{maximum<const char*>(nullptr,"a");});',prefix='#include <cstring>\n#include <stdexcept>\ntemplate<class T> T maximum(T a,T b){return a<b?b:a;}\n')
s(3,'Обычная перегрузка','Контекст содержит maximum(T,T). Добавьте нешаблонную перегрузку для const char*: лексикографический максимум, nullptr → invalid_argument.', 'const char* a="z"; const char* b="aa"; CHECK(maximum(a,b)==a); CHECK(maximum(2,3)==3);',prefix='#include <cstring>\n#include <stdexcept>\ntemplate<class T> T maximum(T a,T b){return a<b?b:a;}\n')
s(3,'Константный указатель','Напишите шаблон const T& first(const T* data,std::size_t size). nullptr → invalid_argument, size=0 → out_of_range; возвращается ссылка на первый элемент.', 'const int a[]={4,2}; CHECK(&first(a,2)==&a[0]); expect_throw<std::out_of_range>([&]{first(a,0);}); expect_throw<std::invalid_argument>([]{first<int>(nullptr,2);});')
s(3,'Тип индекса','Напишите шаблон index_of_min(const T*,std::size_t), результат size_t. Пустой массив или nullptr → invalid_argument; при равных минимумах первый индекс.', 'int a[]={3,1,1}; CHECK(index_of_min(a,3)==1); expect_throw<std::invalid_argument>([&]{index_of_min(a,0);});','static_assert(std::is_same_v<decltype(index_of_min(static_cast<const int*>(nullptr),0)),std::size_t>);')
s(3,'Перехват по ссылке','Напишите std::string message(void (*fn)()). При std::exception верните e.what(); при успехе — пустую строку. Не копируйте объект исключения.', 'CHECK(message(+[]{throw std::out_of_range("index");})=="index"); CHECK(message(+[]{})=="");')
s(3,'Проверяемый доступ','Напишите шаблон checked_access(T*,size_t,size_t), возвращающий T&. nullptr → invalid_argument; индекс вне диапазона → out_of_range.', 'int a[]={2,4}; checked_access(a,2,1)=9; CHECK(a[1]==9); expect_throw<std::out_of_range>([&]{checked_access(a,2,2);});')
s(3,'Явное преобразование','Напишите double ratio(int a,int b): вещественное деление с static_cast. b=0 → invalid_argument.', 'CHECK(ratio(3,2)==1.5); CHECK(ratio(-3,2)==-1.5); expect_throw<std::invalid_argument>([]{ratio(3,0);});')
s(3,'Возвращаемая ссылка','Напишите template-функцию same(T&), возвращающую тот же объект как T&. const-объект тоже должен работать за счёт вывода T.', 'int x=2; same(x)=3; CHECK(x==3); const int y=7; CHECK(&same(y)==&y);')
s(3,'Минимум трёх','Напишите minimum_of_three(T,T,T) по значению, используя только < для сравнения.', 'CHECK(minimum_of_three(3,1,2)==1); CHECK(minimum_of_three(-1,-1,2)==-1); CHECK(minimum_of_three(4,4,4)==4);')
s(3,'Тип пользовательского класса','Напишите maximum(T,T) по значению, опираясь только на <. Не требуйте > или <=.', 'struct Value{int n; bool operator<(const Value& r)const{return n<r.n;}}; CHECK(maximum(Value{3},Value{7}).n==7);')
s(3,'Без потери дроби','Напишите average(A,B) для арифметических типов: double-результат среднего значения без целочисленного деления. Приведение выполняйте до сложения.', 'CHECK(average(2,3)==2.5); CHECK(average(1.5,2)==1.75); CHECK(average(2000000000,2000000000)==2000000000.0);')
s(3,'Пустой массив','Напишите count_equal(const T*,size_t,const T&) -> size_t. nullptr допустим только при size=0; в остальных случаях invalid_argument.', 'int a[]={1,2,1}; CHECK(count_equal(a,3,1)==2); CHECK(count_equal<int>(nullptr,0,1)==0); expect_throw<std::invalid_argument>([]{count_equal<int>(nullptr,2,1);});')
s(3,'Функция-предикат','Напишите template count_if(const T*,size_t,Predicate) -> size_t. Предикат вызывается для каждого элемента. nullptr допустим при нулевом размере.', 'int a[]={-1,0,2,4}; CHECK(count_if(a,4,[](int x){return x>0;})==2); CHECK(count_if<int>(nullptr,0,[](int){return true;})==0);')
s(3,'Константность результата','Напишите шаблон const T& last(const T*,size_t). nullptr или пустой диапазон → invalid_argument.', 'const double a[]={1,2.5}; CHECK(&last(a,2)==&a[1]); expect_throw<std::invalid_argument>([]{last<int>(nullptr,0);});')
s(3,'Специализация bool','Контекст содержит invert(T). Специализируйте для bool: логическое отрицание. Обычный шаблон меняет знак.', 'CHECK(invert(true)==false); CHECK(invert(false)==true); CHECK(invert(3)==-3);',prefix='template<class T> T invert(T v){return -v;}\n')

BOX='#include <cstddef>\n#include <stdexcept>\ntemplate<class T> class Box { T value_; public: explicit Box(const T&); ~Box(); T get() const; void set(const T&); const T& ref() const; };\n'
s(4,'Конструктор вне класса','В контексте Box<T>. Определите только конструктор вне класса, инициализирующий value_ копией аргумента.', 'Box<int> b(7); CHECK(b.get()==7);',prefix=BOX,suffix='\ntemplate<class T> Box<T>::~Box()=default;\ntemplate<class T> T Box<T>::get() const{return value_;}\n')
s(4,'Деструктор вне класса','В контексте Box<T>. Определите только деструктор вне класса. Владения сырой памятью нет; используйте корректное default-определение.', 'Box<int> b(7);',prefix=BOX,suffix='\ntemplate<class T> Box<T>::Box(const T& v):value_(v){}\n')
s(4,'Обычный метод вне класса','В контексте Box<T>. Определите set вне класса, присваивающий value_.', 'Box<int> b(7); b.set(9); CHECK(b.get()==9);',prefix=BOX,suffix='\ntemplate<class T> Box<T>::Box(const T& v):value_(v){}\ntemplate<class T> Box<T>::~Box()=default;\ntemplate<class T> T Box<T>::get() const{return value_;}\n')
s(4,'Результат T вне класса','В контексте Box<T>. Определите get вне класса. Результат — копия value_, метод const.', 'const Box<double> b(2.5); CHECK(b.get()==2.5);',prefix=BOX,suffix='\ntemplate<class T> Box<T>::Box(const T& v):value_(v){}\ntemplate<class T> Box<T>::~Box()=default;\n')
s(4,'const-ссылка вне класса','В контексте Box<T>. Определите ref вне класса. Верните ссылку без права изменения на value_.', 'const Box<int> b(2); CHECK(b.ref()==2);','static_assert(std::is_same_v<decltype(std::declval<const Box<int>&>().ref()),const int&>);',prefix=BOX,suffix='\ntemplate<class T> Box<T>::Box(const T& v):value_(v){}\ntemplate<class T> Box<T>::~Box()=default;\n')
s(4,'Два параметра вне класса','В контексте Fixed<T,Size>. Определите capacity вне класса; верните Size. Не повторяйте значение по умолчанию.', 'const Fixed<int,7> a; const Fixed<double> b; CHECK(a.capacity()==7 && b.capacity()==256);',prefix='template<class T,int Size=256> class Fixed { public: int capacity() const; };\n')
s(4,'Метод производного шаблона','В контексте Derived<T>. Определите get вне класса, читая защищённое value_ зависимой базы.', 'const Derived<int> a; CHECK(a.get()==TYPICAL_ZERO);'.replace('TYPICAL_ZERO','0'),prefix='template<class T> class Base { protected: T value_{}; };\ntemplate<class T> class Derived:public Base<T>{public:T get()const;};\n')
s(4,'Чисто виртуальный контракт','Создайте template<class T> class AbstractStack с чисто виртуальными bool Push(const T&), bool Pop(T&), bool Get(T&) const и виртуальным деструктором.', 'CHECK(std::is_abstract_v<AbstractStack<int>>); CHECK(std::has_virtual_destructor_v<AbstractStack<double>>);')
s(4,'override','Контекст задаёт Base. Создайте Derived с корректным override value, возвращающим 7 для const-объекта.', 'const Derived d; const Base& b=d; CHECK(b.value()==7);',prefix='struct Base{virtual ~Base()=default; virtual int value()const=0;};\n')
s(4,'Вложенный узел','Создайте template<class T> struct List с вложенной public struct Node: поле T value, Node* next; конструктор из const T& и Node*, next по умолчанию nullptr.', 'List<int>::Node a(2),b(3,&a); CHECK(a.next==nullptr && b.next==&a && b.value==3);')
s(4,'Полная специализация класса','Контекст задаёт Box<T> с kind()==1. Полностью специализируйте Box<char*>: const-метод kind возвращает 2.', 'CHECK(Box<int>{}.kind()==1 && Box<char*>{}.kind()==2);',prefix='template<class T> struct Box{int kind()const{return 1;}};\n')
s(4,'Специализация метода','Контекст задаёт Box<T>::kind. Специализируйте только kind для Box<int>, результат 7.', 'CHECK(Box<int>{}.kind()==7 && Box<double>{}.kind()==1);',prefix='template<class T> struct Box{int kind()const{return 1;}};\n')
s(4,'Проверяемый указатель','Контекст задаёт Shape, Circle. Напишите Circle* as_circle(Shape*), используя dynamic_cast.', 'Circle c; Shape b; CHECK(as_circle(&c)==&c); CHECK(as_circle(&b)==nullptr); CHECK(as_circle(nullptr)==nullptr);',prefix='struct Shape{virtual ~Shape()=default;}; struct Circle:Shape{};\n')
s(4,'Проверяемая ссылка','Контекст задаёт Shape, Circle. Напишите Circle& circle_ref(Shape&), при несовпадении типа ожидается bad_cast.', 'Circle c; Shape b; CHECK(&circle_ref(c)==&c); expect_throw<std::bad_cast>([&]{circle_ref(b);});',prefix='#include <typeinfo>\nstruct Shape{virtual ~Shape()=default;}; struct Circle:Shape{};\n')
s(4,'Сравнение typeid','Контекст задаёт Shape, Circle. Напишите bool exact_circle(const Shape&): true лишь для точного динамического Circle, включая отличие от производного класса.', 'Circle c; Shape b; struct Small:Circle{}; Small d; CHECK(exact_circle(c)); CHECK(!exact_circle(b) && !exact_circle(d));',prefix='#include <typeinfo>\nstruct Shape{virtual ~Shape()=default;}; struct Circle:Shape{};\n')
s(4,'Числовой static_cast','Напишите int truncate(double x), преобразующий представимое значение к int. Тесты не выходят за диапазон int.', 'CHECK(truncate(2.9)==2 && truncate(-2.9)==-2 && truncate(0)==0);')
s(4,'const_cast без UB','Напишите int* mutable_alias(const int* p), снимающий const. Контракт: исходный объект действительно неконстантный; nullptr сохраняется.', 'int n=3; const int* p=&n; *mutable_alias(p)=7; CHECK(n==7 && mutable_alias(nullptr)==nullptr);')
s(4,'Представление байтов','Напишите const unsigned char* bytes(const int& value) через reinterpret_cast. Просмотр представления разрешён, запись не требуется.', 'int x=7; const auto* p=bytes(x); CHECK(static_cast<const void*>(p)==static_cast<const void*>(&x));')
s(4,'Запрет копирования','Создайте class Owner с конструктором по умолчанию, удалёнными копирующим конструктором и копирующим присваиванием. Память в этом упражнении выделять не нужно.', 'Owner o; (void)o;','static_assert(!std::is_copy_constructible_v<Owner> && !std::is_copy_assignable_v<Owner>);')
s(4,'Виртуальное уничтожение','Создайте Base с виртуальным деструктором и Derived, принимающий int& counter. Деструктор Derived увеличивает counter на 1.', 'int count=0; Base* p=new Derived(count); delete p; CHECK(count==1);',memory=True)

# New names and values prevent the exam from merely replaying the same source.
s(5,'Экзамен · присваивание','Создайте Record(int) с value() const и копирующим присваиванием. Поддержите самоприсваивание и цепочку; хранение — один int.', 'Record a(2),b(5),c(9); CHECK(&(a=b=c)==&a); CHECK(a.value()==9); a=a; CHECK(a.value()==9);')
s(5,'Экзамен · копирующий конструктор','Создайте Record(int) с явно объявленным копирующим конструктором и value() const.', 'const Record a(-9); Record b(a); CHECK(b.value()==-9);')
s(5,'Экзамен · константный индекс','Создайте Pair(int,int) с двумя перегрузками [], возвращающими ссылки нужной константности. Индекс вне 0..1 → out_of_range.', 'Pair p(4,8); p[1]=9; const Pair& r=p; CHECK(r[1]==9); expect_throw<std::out_of_range>([&]{(void)r[2];});','static_assert(std::is_same_v<decltype(std::declval<const Pair&>()[0]),const int&>);')
s(5,'Экзамен · friend','Создайте Token(int) с приватным значением и дружественным выводом в формате <число>.', 'std::ostringstream o; const Token t(6); CHECK(&(o<<t)==&o); CHECK(o.str()=="<6>");')
s(5,'Экзамен · тип результата','Напишите subtract(A,B) с типом результата выражения a-b.', 'CHECK(subtract(8,2.5)==5.5);','static_assert(std::is_same_v<decltype(subtract(8,2.5)),double>);')
s(5,'Экзамен · внешний метод','В контексте Store<T>. Определите метод read вне класса.', 'const Store<int> s; CHECK(s.read()==0);',prefix='template<class T> class Store{T v_{};public: const T& read()const;};\n')
s(5,'Экзамен · параметр-значение','Создайте template<class T,int N=8> class Capacity, метод count() const возвращает N. Определение метода — вне класса.', 'CHECK(Capacity<double>{}.count()==8); CHECK((Capacity<int,3>{}.count()==3));')
s(5,'Экзамен · специализация','В контексте tag(T). Специализируйте для double, возвращая 2; остальные типы сохраняют 1.', 'CHECK(tag(2.0)==2 && tag(2)==1);',prefix='template<class T> int tag(T){return 1;}\n')
s(5,'Экзамен · наследование','Создайте template<class T> struct Derived, публично наследующий Base<T>. Метод get() const возвращает protected value_.', 'CHECK(Derived<int>{}.get()==0);',prefix='template<class T> struct Base{protected:T value_{};};\n')
s(5,'Экзамен · абстрактный интерфейс','Создайте template<class T> class Reader с чисто виртуальным const T& Get() const и виртуальным деструктором.', 'CHECK(std::is_abstract_v<Reader<int>> && std::has_virtual_destructor_v<Reader<int>>);')
s(5,'Экзамен · RTTI указатель','Контекст задаёт B и D. Напишите D* checked(B*), возвращающий nullptr при неудаче.', 'B b; D d; CHECK(checked(&b)==nullptr && checked(&d)==&d);',prefix='struct B{virtual ~B()=default;};struct D:B{};\n')
s(5,'Экзамен · RTTI ссылка','Контекст задаёт B и D. Напишите D& checked(B&), бросающий bad_cast при неудаче.', 'B b; D d; CHECK(&checked(d)==&d); expect_throw<std::bad_cast>([&]{checked(b);});',prefix='#include <typeinfo>\nstruct B{virtual ~B()=default;};struct D:B{};\n')
s(5,'Экзамен · try/catch','Напишите bool attempt(void (*fn)()): true при успехе, false при invalid_argument; другие исключения не перехватывать.', 'CHECK(attempt(+[]{})); CHECK(!attempt(+[]{throw std::invalid_argument("x");})); expect_throw<std::out_of_range>([]{attempt(+[]{throw std::out_of_range("x");});});')
s(5,'Экзамен · массив','Напишите int* fill(std::size_t n,int v): новый new[]-массив с n копиями v, n=0 разрешён. Освобождает вызывающий.', 'int* p=fill(4,-3); for(int i=0;i<4;++i) CHECK(p[i]==-3); delete[] p; delete[] fill(0,9);',memory=True)
s(5,'Экзамен · освобождение','Напишите dispose(double*&): delete[] массива и обнуление исходного указателя.', 'double* p=new double[3]; dispose(p); CHECK(p==nullptr); dispose(p);',memory=True)
s(5,'Экзамен · переполнение','Напишите std::size_t checked_product(size_t a,size_t b). Переполнение произведения → length_error; умножение на ноль разрешено.', 'CHECK(checked_product(3,7)==21); CHECK(checked_product(0,std::numeric_limits<std::size_t>::max())==0); expect_throw<std::length_error>([]{checked_product(std::numeric_limits<std::size_t>::max(),2);});')
s(5,'Экзамен · перегрузка C-строк','Напишите minimum(const char*,const char*) по содержимому. При равенстве вернуть первый указатель. nullptr → invalid_argument.', 'const char a[]="az",b[]="ba"; CHECK(minimum(a,b)==a); expect_throw<std::invalid_argument>([]{minimum(nullptr,"x");});')
s(5,'Экзамен · внешнее присваивание','В контексте Cell<T>. Определите копирующий operator= вне класса, возвращающий ссылку на текущий объект.', 'Cell<int> a(3),b(9); CHECK(&(a=b)==&a && a.get()==9);',prefix='template<class T> class Cell{T v_;public: explicit Cell(T v):v_(v){} Cell& operator=(const Cell&);T get()const{return v_;}};\n')
s(5,'Экзамен · noexcept','Напишите class State с empty() const noexcept, всегда возвращающим true, и noexcept-деструктором.', 'const State s; CHECK(s.empty());','static_assert(noexcept(std::declval<const State&>().empty())); static_assert(std::is_nothrow_destructible_v<State>);')
s(5,'Экзамен · независимый буфер','Напишите char* duplicate(const char*) через new[]. nullptr → invalid_argument, поддержите пустую строку. Владение возвращается вызывающему.', 'char a[]="exam"; char* b=duplicate(a); a[0]=char(88); CHECK(std::strcmp(b,"exam")==0); delete[] b; b=duplicate(""); CHECK(b[0]==0); delete[] b;',memory=True)
